{{!-- Styling parameters: class, titleClass, descriptionClass, formClass, inputClass, buttonClass --}}
{{#with this as |ghostcnStyles|}}
{{!--
  Component: Newsletter Form
  Usage: {{> "components/newsletter-form" title="Subscribe to our newsletter" description="Get the latest posts delivered right to your inbox."}}
--}}
{{#if @site.members_enabled}}
{{#unless @site.members_invite_only}}
{{#if @site.allow_self_signup}}
{{#unless @member}}
<section class="gh-newsletter-form{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}">
    <div class="gh-newsletter-heading">
        <h3 class="gh-newsletter-title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">
            {{#if title}}{{title}}{{else}}Subscribe to our newsletter{{/if}}
        </h3>
        <p class="gh-newsletter-desc{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">
            {{#if description}}{{description}}{{else}}Get the latest stories, news, and perspectives delivered directly to your inbox.{{/if}}
        </p>
    </div>

    {{!-- Ghost native members form handling --}}
    {{#if @site.portal_signup_checkbox_required}}
    <a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}" href="#/portal/signup" data-portal="signup">Subscribe</a>
    {{else}}
    <form data-members-form="subscribe" class="gh-newsletter-fields{{#if ghostcnStyles.formClass}} {{ghostcnStyles.formClass}}{{/if}}">
        <input
            data-members-email
            type="email"
            aria-label="Email address"
            autocomplete="email"
            required
            placeholder="jamie@example.com"
            class="gh-newsletter-input{{#if ghostcnStyles.inputClass}} {{ghostcnStyles.inputClass}}{{/if}}"
        />
        <button type="submit" class="gh-newsletter-btn{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}}">
            <span class="button-text">Subscribe</span>
        </button>

        {{!-- Ghost automatic states (hidden by default, shown via Ghost Portal JS) --}}
        <div class="gh-newsletter-msg-success message-success" role="status" data-members-success>
            <svg aria-hidden="true" viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8.5 6.5 12 13 4"/></svg>
            <span>Check your inbox to confirm your subscription!</span>
        </div>
        <div class="gh-newsletter-msg-error message-error" role="alert" data-members-error>
            <svg aria-hidden="true" viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>
            <span>Please enter a valid email address.</span>
        </div>
    </form>
    {{/if}}
</section>
{{/unless}}
{{/if}}
{{/unless}}
{{/if}}
{{/with}}

/* ghostcn: Newsletter Form Styles */
.gh-newsletter-form {
    box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b);
    margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px));
    font-family: inherit;
    font-size: var(--ghcn-text-body, 16px);
    line-height: 1.5;
    padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px));
    text-align: center;
    width: min(100% - 32px, 704px);
    margin-inline: auto;
}

.gh-newsletter-form *,
.gh-newsletter-form *::before,
.gh-newsletter-form *::after {
    box-sizing: border-box;
}

.gh-newsletter-heading { margin-bottom: 16px; }

.gh-newsletter-title {
    font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance;
    margin: 0 0 8px;
    color: inherit;
}

.gh-newsletter-desc {
    color: var(--muted-foreground, #71717a);
    font-size: var(--ghcn-text-small, 14px);
    line-height: 1.5;
    margin: 0 auto;
    max-width: 448px;
}

.gh-newsletter-fields {
    display: grid;
    gap: var(--ghcn-control-gap, 8px);
    max-width: 448px;
    margin: 0 auto;
    position: relative;
}

@media (min-width: 640px) {
    .gh-newsletter-fields {
        grid-template-columns: minmax(0, 1fr) auto;
    }
}

.gh-newsletter-input {
    min-width: 0;
    min-height: var(--ghcn-control-height, 40px);
    padding: var(--ghcn-control-padding, 8px 14px);
    background-color: var(--background, #ffffff);
    color: var(--foreground, #09090b);
    border: 1px solid var(--input, #e4e4e7);
    border-radius: var(--ghcn-control-radius, var(--radius, 8px));
    font-family: inherit;
    font-size: var(--ghcn-text-small, 14px);
    line-height: 1.25;
}

.gh-newsletter-form:focus-visible, :where(.gh-newsletter-form) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }

.gh-newsletter-btn {
    background-color: var(--primary, var(--ghost-accent-color, #18181b));
    color: var(--primary-foreground, #ffffff);
    min-height: var(--ghcn-control-height, 40px);
    padding: var(--ghcn-control-padding, 8px 14px);
    border-radius: var(--ghcn-control-radius, var(--radius, 8px));
    font-family: inherit;
    font-size: var(--ghcn-text-small, 14px);
    font-weight: 600;
    line-height: 1.25;
    border: 1px solid transparent;
    cursor: pointer;
    transition: opacity 0.15s ease;
}

.gh-newsletter-btn:hover {
    opacity: 0.9;
}

.gh-newsletter-msg-success,
.gh-newsletter-msg-error {
    display: none;
    grid-column: 1 / -1;
    font-size: 12px;
    font-weight: 500;
}

.gh-newsletter-fields.success .gh-newsletter-msg-success,
.gh-newsletter-fields.error .gh-newsletter-msg-error {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
}

.gh-newsletter-form .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.gh-newsletter-msg-success {
    color: var(--success, #15803d);
}

.gh-newsletter-msg-error {
    color: var(--destructive, #dc2626);
}
